\section{Bounded partitions}

Let $p_{\le b}(m)$ be the number of partitions of $m$ into parts of size at most $b$, with
$p_{\le b}(0)=1$ and $p_{\le0}(m)=[m=0]$.

\begin{definition}\label{def:pb}
Choosing the multiplicity $c$ of the largest allowed part,
\[
p_{\le b+1}(m)=\sum_{c=0}^{\lfloor m/(b+1)\rfloor}p_{\le b}\bigl(m-c(b+1)\bigr).
\]
\end{definition}

That this recursion counts the intended objects is a theorem, not a convention: one exhibits the
finite set of weakly decreasing lists of integers in $[1,b]$ summing to $m$, characterises its
membership, and shows its cardinality obeys the recursion. The structural step is that a weakly
decreasing list bounded by $b+1$ splits uniquely as a block of copies of $b+1$ followed by a list
bounded by $b$.

\begin{proposition}[Euler's recurrence]\label{prop:euler}
For $b+1\le m$,
\[
p_{\le b+1}(m)=p_{\le b}(m)+p_{\le b+1}\bigl(m-(b+1)\bigr),
\]
while $p_{\le b+1}(m)=p_{\le b}(m)$ for $m<b+1$.
\end{proposition}

\begin{proof}[Proof sketch]
Split Definition~\ref{def:pb} according to $c=0$ (the part $b+1$ is unused) or $c\ge1$ (remove one
copy of $b+1$ and reindex).
\end{proof}

\begin{proposition}\label{prop:pbounds}
\begin{enumerate}
\item $p_{\le b}(m)\le p_{\le b+1}(m)$, and $p_{\le b}(\cdot)$ is non-decreasing for $b\ge1$.
\item $p_{\le b}(m)\le(m+1)^{b}$.
\item $2^{\,b}\le p_{\le b+1}(m)$ whenever $b(b+3)\le2m$.
\end{enumerate}
\end{proposition}

\begin{proof}[Proof sketch]
(1) The $c=0$ term of Definition~\ref{def:pb} already contributes $p_{\le b}(m)$; monotonicity in
$m$ follows by strong induction from Proposition~\ref{prop:euler}. (2) Each of the at most $m+1$
summands is bounded inductively. (3) Induct on $b$: the hypothesis $b(b+3)\le2m$ guarantees that
both summands of Proposition~\ref{prop:euler} still satisfy the inductive hypothesis, so the count
doubles at each step.
\end{proof}

Part (3) drives the lower bound of Section~\ref{sec:growth}: once the area is quadratically large
compared with the part ceiling, raising the ceiling by one doubles the count.

\section{The core decomposition}

\begin{definition}[slope convolution]\label{def:conv}
For $b,m\ge0$ set $\displaystyle c_{b}(m):=\sum_{i+j=m}p_{\le b}(i)p_{\le b}(j)$. Thus
$c_{0}(m)=[m=0]$ and $c_{1}(m)=m+1$.
\end{definition}

\begin{definition}[layer decomposition]\label{def:layers}
$\displaystyle a(n):=\sum_{k\,:\,k^{2}\le n}c_{k-1}\bigl(n-k^{2}\bigr)$.
\end{definition}

\begin{definition}[assembly map]\label{def:phi}
For $k\ge1$ and weakly decreasing lists $\ell,r$ of positive integers with all entries $<k$, put
\[
\Phi(k,\ell,r):=\overleftarrow{\ell}\ \Vert\ \underbrace{(k,k,\dots,k)}_{k}\ \Vert\ r,
\]
where $\overleftarrow{\ell}$ denotes $\ell$ reversed. For $k=0$ both slopes are empty and $\Phi$
is the empty list.
\end{definition}

\begin{theorem}[the decomposition is a bijection]\label{thm:bij}
$\Phi$ is a bijection from
$\{(k,\ell,r): k^{2}\le n,\ \ell,r\text{ partitions into parts}<k,\ |\ell|+|r|=n-k^{2}\}$
onto the set of square-core stacks of area $n$.
\end{theorem}

\begin{proof}[Proof sketch]
\emph{Well-definedness.} $\overleftarrow{\ell}$ is weakly increasing and $r$ weakly decreasing, so
the concatenation is unimodal; all entries are $\ge1$; the maximum is $k$ since both slopes are
bounded by $k-1$; and $k$ occurs exactly $k$ times, namely in the core. The area is
$|\ell|+k^{2}+|r|=n$.

\emph{Surjectivity.} If $L$ is a square-core stack with maximum $k\ge1$, unimodality forces the
$k$ occurrences of $k$ to be consecutive, so $L=A\Vert(k,\dots,k)\Vert B$ with $A$ weakly
increasing, $B$ weakly decreasing, and all entries of $A,B$ strictly below $k$ (an entry equal to
$k$ would enlarge the plateau). Take $\ell=\overleftarrow{A}$, $r=B$.

\emph{Injectivity.} The maximum recovers $k$; the maximal run of $k$'s locates the core uniquely;
deleting it recovers $A$ and $B$.
\end{proof}

\begin{theorem}[counting formula]\label{thm:count}
$\displaystyle a(n)=\sum_{k^{2}\le n}\ \sum_{i+j=n-k^{2}}p_{\le k-1}(i)\,p_{\le k-1}(j)$.
\end{theorem}

Layer $k=1$ contributes $[n=1]$, and layer $k=2$ contributes $c_{1}(n-4)=n-3$ for $n\ge4$: the
$2\times2$ block with a tail of unit columns split between the two sides.

\section{Generating functions}

Work in $\Z[[x]]$ and set $F_{b}(x):=\sum_{m\ge0}p_{\le b}(m)x^{m}$.

\begin{theorem}[truncated Euler product]\label{thm:euler}
For every $b\ge0$, $\ \displaystyle F_{b}(x)\prod_{i=1}^{b}(1-x^{i})=1$.
\end{theorem}

\begin{proof}[Proof sketch]
Proposition~\ref{prop:euler} is equivalent to $F_{b+1}(x)(1-x^{b+1})=F_{b}(x)$: extracting the
coefficient of $x^{m}$ reproduces the two cases $m\ge b+1$ and $m<b+1$ of the recurrence. Induct
on $b$ from $F_{0}=1$.
\end{proof}

\begin{theorem}[generating function]\label{thm:gf}
With $L_{k}(x):=F_{k-1}(x)^{2}x^{k^{2}}$ one has
$L_{k}(x)\bigl(\prod_{i=1}^{k-1}(1-x^{i})\bigr)^{2}=x^{k^{2}}$ and
\[
\sum_{n\ge0}a(n)x^{n}=\sum_{k\ge0}\frac{x^{k^{2}}}{\prod_{i=1}^{k-1}(1-x^{i})^{2}} .
\]
\end{theorem}

\begin{proof}[Proof sketch]
The coefficient of $x^{m}$ in $F_{b}^{2}$ is $c_{b}(m)$ by the Cauchy product, and multiplication
by $x^{k^{2}}$ shifts. Hence for any $N\ge n$ the coefficient of $x^{n}$ in $\sum_{k\le N}L_{k}$
is $\sum_{k^{2}\le n}c_{k-1}(n-k^{2})=a(n)$: layers with $k^{2}>n$ contribute nothing, so the
family is summable. The product identity is Theorem~\ref{thm:euler} squared.
\end{proof}

\begin{remark}[the Durfee near-miss]\label{rem:durfee}
The Durfee square decomposition gives
$\sum_{n}p(n)x^{n}=\sum_{k}x^{k^{2}}\prod_{i=1}^{k}(1-x^{i})^{-2}$. Our series deletes the last
factor $(1-x^{k})^{-1}$ from each layer. As $(1-x^{k})^{-1}$ has non-negative coefficients, the
comparison is coefficientwise favourable to $p$, layer by layer, suggesting $a(n)\le p(n)$ for all
$n$ (verified numerically past $n=4000$).
\end{remark}

\section{Positivity, the gap, and monotonicity}

\begin{theorem}\label{thm:lin}
For $n\ge4$, $a(n)\ge n-3$.
\end{theorem}

\begin{proof}
The layer $k=2$ alone contributes $c_{1}(n-4)=n-3$, and all layers are non-negative.
\end{proof}

\begin{theorem}[vanishing set]\label{thm:zero}
$a(n)=0$ if and only if $n\in\{2,3\}$.
\end{theorem}

\begin{proof}
For $n\ge4$ use Theorem~\ref{thm:lin}; $a(0)=a(1)=1$ directly. For $n=2$: the maximum is $1$ or
$2$; if $k=1$ the plateau has $2$ columns but needs $1$; if $k=2$ it has $1$ column but needs $2$.
For $n=3$ the profiles $(1,1,1)$, $(1,2)$, $(2,1)$, $(3)$ all fail likewise.
\end{proof}

\begin{theorem}[strict monotonicity]\label{thm:strict}
For $n\ge4$, $a(n)<a(n+1)$.
\end{theorem}

\begin{proof}[Proof sketch]
Compare layer sums termwise: every layer $k$ satisfies $c_{k-1}(n-k^{2})\le c_{k-1}(n+1-k^{2})$
since $c_{b}$ is non-decreasing for $b\ge1$ (a convolution of non-decreasing non-negative
sequences), and layers switching on only add. The layer $k=2$ increases strictly, from $n-3$ to
$n-2$.
\end{proof}

\section{Convexity, and the failure of log-concavity}

\begin{lemma}[difference rule for convolutions]\label{lem:diff}
Let $g,f:\N\to\Z$ and let $d(0)=f(0)$, $d(i+1)=f(i+1)-f(i)$. Then for all $m$,
\[
\sum_{i=0}^{m+1}g(i)f(m+1-i)-\sum_{i=0}^{m}g(i)f(m-i)=\sum_{i=0}^{m+1}g(i)d(m+1-i).
\]
\end{lemma}

\begin{proof}[Proof sketch]
Pair the first $m+1$ terms using $f(m+1-i)-f(m-i)=d(m+1-i)$; the leftover $g(m+1)f(0)=g(m+1)d(0)$
supplies the last summand. In series form this is $(1-x)(g*f)=g*\bigl((1-x)f\bigr)$.
\end{proof}

\begin{proposition}[second differences of a self-convolution]\label{prop:selfconv}
If $f$ is non-decreasing and $S=f*f$, then
$S(m+2)-2S(m+1)+S(m)=\sum_{i+j=m+2}d(i)d(j)\ \ge0$.
\end{proposition}

\begin{proof}[Proof sketch]
Apply Lemma~\ref{lem:diff} twice, once in each argument (the finite convolution is commutative):
$(1-x)^{2}(f*f)=\bigl((1-x)f\bigr)^{*2}$. Monotonicity of $f$ gives $d\ge0$, and a convolution of
non-negative sequences is non-negative.
\end{proof}

\begin{theorem}[convexity]\label{thm:convex}
For $b\ge1$ and all $m$, $2c_{b}(m+1)\le c_{b}(m)+c_{b}(m+2)$; consequently, for $n\ge2$,
\[
2\,a(n+1)\le a(n)+a(n+2).
\]
\end{theorem}

\begin{proof}[Proof sketch]
The layer statement is Proposition~\ref{prop:selfconv} with $f=p_{\le b}$. For $a$, write the three
values as sums over a common finite range of layer functions and check convexity layer by layer;
the degenerate layers $k\le1$ are checked directly, and layers switching on between $n$ and $n+2$
contribute non-negative terms on the larger side only.
\end{proof}

\begin{corollary}
The increments $\Delta a(n)=a(n+1)-a(n)$ are non-decreasing for $n\ge1$.
\end{corollary}

\begin{theorem}[divergent increments]\label{thm:gaps}
$\Delta a(n)\to\infty$. Quantitatively, if $n\ge2$ and $(n+1)^{2}\le a(n+1)$ then
$\Delta a(n)\ge n$.
\end{theorem}

\begin{proof}[Proof sketch]
Convexity and telescoping from $a(2)=0$ give $a(j+2)\le j\,\Delta a(j+1)$ by induction; combine
with the superpolynomial growth of Theorem~\ref{thm:superpoly} for $d=2$.
\end{proof}

\begin{theorem}[log-concavity fails]\label{thm:logconc}
It is \emph{not} true that $a(n)a(n+2)\le a(n+1)^{2}$ for all $n\ge4$: indeed
$a(8)^{2}=25<28=a(7)a(9)$.
\end{theorem}

Thus convexity and log-concavity genuinely separate here: new layers switch on at the perfect
squares, producing local surges that convexity tolerates but log-concavity does not.

\section{The third core layer, exactly}

The layers $k=0,1,2$ are two deltas and the linear function $m\mapsto m+1$. The first layer with
arithmetic content is $k=3$, governed by $c_{2}=p_{\le2}*p_{\le2}$. Since $p_{\le1}(m)=1$ and
$p_{\le2}(m)=\lfloor m/2\rfloor+1=:g(m)$, one has
$\sum_{j\le m}p_{\le2}(j)=(\lfloor m/2\rfloor+1)(\lfloor(m+1)/2\rfloor+1)$ and the two-step
recurrence
\[
c_{2}(m+2)=c_{2}(m)+g(m)g(m+1)+g(m+1)+g(m+2).
\]

\begin{theorem}[closed form]\label{thm:layer3}
For all $s\ge0$,
\[
24\,c_{2}(2s)=(2s+2)(2s+3)(2s+4),\qquad 24\,c_{2}(2s+1)=(2s+2)(2s+4)(2s+6).
\]
Equivalently $c_{2}(m)=\frac{(m+2)(m+3)(m+4)}{24}$ for even $m$ and
$c_{2}(m)=\frac{(m+1)(m+3)(m+5)}{24}$ for odd $m$.
\end{theorem}

\begin{proof}[Proof sketch]
Both sides satisfy the two-step recurrence and agree at $m=0,1$ (values $1,2$); induct in steps of
two, the inductive step reducing to a polynomial identity in $s$.
\end{proof}

So $c_{2}$ is a quasi-polynomial of degree $3$ and period $2$: two cubics with the same leading
coefficient $1/24$ but different lower-order terms. That discrepancy destroys higher-order
convexity.

\begin{theorem}[exact third differences]\label{thm:d3}
With $\Delta^{3}u(m)=u(m+3)-3u(m+2)+3u(m+1)-u(m)$, for all $t\ge0$,
\[
\Delta^{3}c_{2}(2t)=-(t+2),\qquad \Delta^{3}c_{2}(2t+1)=t+3 .
\]
\end{theorem}

\begin{corollary}\label{cor:not3layer}
$c_{2}(2t+3)+3c_{2}(2t+1)<3c_{2}(2t+2)+c_{2}(2t)$ for every $t\ge0$: $3$-convexity of the third
layer fails at every even argument, with amplitude growing linearly.
\end{corollary}

\begin{theorem}[$a$ is not $3$-convex]\label{thm:not3}
It is \emph{not} true that $3a(n+2)+a(n)\le a(n+3)+3a(n+1)$ for all $n\ge4$: indeed
\[
a(10)+3a(8)=9+15=24\ <\ 25=21+4=3a(9)+a(7).
\]
\end{theorem}

Convexity is therefore exactly the right regularity statement for this family: it holds, and both
natural strengthenings fail --- the higher-order one infinitely often.

\section{Growth: $\log a(n)\asymp\sqrt n$}\label{sec:growth}

\begin{theorem}\label{thm:lower}
If $3m^{2}+11m+8\le2n$ then $2^{\,m}\le a(n)$.
\end{theorem}

\begin{proof}[Proof sketch]
Take the single layer $k=m+2$, present because the hypothesis forces $(m+2)^{2}\le n$. With
$N=n-(m+2)^{2}$ we have $a(n)\ge c_{m+1}(N)\ge p_{\le m+1}(N)$ (keep the term $i=0$), and the
hypothesis is calibrated so that $m(m+3)\le2N$, so Proposition~\ref{prop:pbounds}(3) applies.
\end{proof}

\begin{corollary}\label{cor:lower}
For $n\ge100$, $\ \frac{\sqrt n-2}{2}\log2\le\log a(n)$.
\end{corollary}

\begin{proof}[Proof sketch]
Take $m=\lfloor\lfloor\sqrt n\rfloor/2\rfloor$; elementary estimates show both that the hypothesis
of Theorem~\ref{thm:lower} holds and that $m\ge(\sqrt n-2)/2$.
\end{proof}

\begin{proposition}[crude upper bound]\label{prop:crude}
$a(n)\le(n+1)^{2\lfloor\sqrt n\rfloor+2}$; hence $\log a(n)\le4\sqrt n(\log2+\log n)$ for $n\ge1$.
\end{proposition}

\begin{proof}[Proof sketch]
From $p_{\le b}(m)\le(m+1)^{b}$ one gets $c_{b}(m)\le(m+1)^{2b+1}$; each present layer has
$k\le\lfloor\sqrt n\rfloor$, and there are at most $n+1$ terms in the formal sum.
\end{proof}

The spurious factor $\log n$ is removed by a Hardy--Ramanujan estimate uniform in the ceiling.

\begin{lemma}[Rankin bound]\label{lem:rankin}
For $0<x<1$ and all $b,m$, $\ \displaystyle p_{\le b}(m)x^{m}\le\prod_{i=1}^{b}(1-x^{i})^{-1}$.
\end{lemma}

\begin{proof}[Proof sketch]
The left-hand side is a single term of the series $F_{b}(x)$, which has non-negative coefficients
and equals the right-hand side by Theorem~\ref{thm:euler}.
\end{proof}

\begin{lemma}[two-regime estimate]\label{lem:tworegime}
Let $x=1-1/N$ with $N\ge2$. Then $\ \sum_{i=1}^{b}-\log(1-x^{i})\le6N$, uniformly in $b$.
\end{lemma}

\begin{proof}[Proof sketch]
Split at $i=N$. For $i\le N$ one has the elementary bound $1-x^{i}\ge i/(8N)$, coming from
$(1-1/N)^{N}\ge1/8$ (a consequence of $N^{N}\le N!\,e^{N}$) together with convexity; hence
$\sum_{i\le N}-\log(1-x^{i})\le N\log(8N)-\log N!\le cN$, using $\log N!\ge N\log N-N$. For $i>N$
one has $x^{i}\le x^{N}\le1/2$, so $-\log(1-x^{i})\le2x^{i}$, and
$\sum_{i>N}x^{i}\le(1-x)^{-1}=N$.
\end{proof}

\begin{theorem}[uniform Hardy--Ramanujan bound]\label{thm:HR}
For all $b,m$: $\ \log p_{\le b}(m)\le8\sqrt m+12$.
\end{theorem}

\begin{proof}[Proof sketch]
Take logarithms in Lemma~\ref{lem:rankin} with $x=1-1/N$:
$\log p_{\le b}(m)\le m\log(1/x)+\sum_{i\le b}-\log(1-x^{i})\le \frac{m}{N-1}+6N$ by
Lemma~\ref{lem:tworegime}. Choose $N\approx\sqrt m$ to balance.
\end{proof}

Uniformity in $b$ is the crucial point: it treats all $\Theta(\sqrt n)$ layers at once.

\begin{theorem}[sharp two-sided bound]\label{thm:sharp}
For $n\ge100$,
\[
\frac{\sqrt n-2}{2}\log2\ \le\ \log a(n)\ \le\ 30\sqrt n .
\]
In particular $\log a(n)\asymp\sqrt n$.
\end{theorem}

\begin{proof}[Proof sketch]
The lower bound is Corollary~\ref{cor:lower}. For the upper bound, Theorem~\ref{thm:HR} gives
$p_{\le b}(m)\le e^{8\sqrt m+12}$, hence $c_{b}(M)\le(M+1)e^{16\sqrt M+24}$ using
$\sqrt i+\sqrt j\le2\sqrt M$ for $i+j=M$. Summing over the at most $\sqrt n+1$ present layers gives
$\log a(n)\le16\sqrt n+2\log(n+1)+24$, and $2\log(n+1)+24\le14\sqrt n$ for $n\ge100$.
\end{proof}

\begin{theorem}[superpolynomial growth]\label{thm:superpoly}
For every $d$ there is $N$ with $n^{d}\le a(n)$ for all $n\ge N$.
\end{theorem}

\begin{proof}[Proof sketch]
Theorem~\ref{thm:lower} gives $2^{m}\le a(n)$ with $m\asymp\sqrt n$, while $n^{d}$ is polynomial in
$m$; every polynomial is eventually dominated by $2^{m}$.
\end{proof}

\begin{theorem}[vanishing entropy density]\label{thm:entropy}
$\displaystyle\lim_{n\to\infty}\frac{\log a(n)}{n}=0$.
\end{theorem}

\begin{proof}[Proof sketch]
Squeeze: $0\le\log a(n)/n\le4\log2/\sqrt n+4\log n/\sqrt n\to0$ by Proposition~\ref{prop:crude} and
positivity of $a(n)$ for $n\ge4$; Theorem~\ref{thm:sharp} gives the stronger $O(1/\sqrt n)$.
\end{proof}

\section{Physical interpretation}

Rotated by ninety degrees, a stack polyomino is a discrete solid-on-solid interface constrained to
have a single hump. The area $n$ is the particle number, $a(n)$ the size of the configuration
space, $S(n)=\log a(n)$ the microcanonical entropy.

\emph{Vanishing free energy.} Theorem~\ref{thm:entropy} says $S(n)/n\to0$. Unrestricted polyominoes
number roughly $\lambda^{n}$ with the Klarner constant $\lambda\approx4.06$, so they have entropy
density $\log\lambda>0$ and extensive disorder. Unimodality plus a square crown collapses this: the
model is rigid, with entropy only of order $\sqrt n$, all freedom residing in the $O(\sqrt n)$
effective degrees of freedom of the two slopes.

\emph{The $\sqrt n$ exponent.} $S(n)\asymp\sqrt n$ is the signature of a one-dimensional bosonic
system: the number of states of a 1D Bose gas at energy $n$ is
$p(n)\sim\frac{1}{4n\sqrt3}\exp\bigl(\pi\sqrt{2n/3}\bigr)$. Our layers are exactly two such bosonic
slopes cut off at the core height.

\emph{The core as a confining potential.} In $\sum_{k}x^{k^{2}}\prod_{i<k}(1-x^{i})^{-2}$, the
factor $x^{k^{2}}$ penalises a tall core while the truncated Euler product rewards it with slope
entropy. The next section quantifies this competition.

\section{Discussion and open problems}

\subsection{The exact constant}
The proved bounds trap $\log a(n)/\sqrt n$ between $\approx0.34$ and $30$. Numerically the ratio is
$1.765$ at $n=100$, $2.137$ at $n=500$, $2.241$ at $n=1000$, $2.290$ at $n=1500$ and $2.381$ at
$n=4000$: a slow climb toward $\pi\sqrt{2/3}=2.5650996\ldots$

\begin{conjecture}\label{conj:HR}
$\log a(n)\sim\pi\sqrt{2n/3}$; equivalently $a(n)$ and $p(n)$ have the same exponential order.
\end{conjecture}

\emph{Heuristic.} Set $x=e^{-t}$, $t\to0^{+}$, and analyse
$\Phi(t)=\sum_{k}e^{-k^{2}t}\prod_{i<k}(1-e^{-it})^{-2}$ by a saddle point in $k$. The logarithm of
the $k$-th term is
\[
-k^{2}t+\frac{2}{t}\int_{0}^{kt}-\log\bigl(1-e^{-s}\bigr)\,ds+o(1/t),
\]
and stationarity in $k$ reads $-2kt+2\bigl(-\log(1-e^{-kt})\bigr)=0$, i.e.\ $e^{-kt}=1-e^{-kt}$,
i.e.\ $kt=\log2$. At that saddle the loss $-k^{2}t$ from the square core is exactly compensated by
the gain from the last stretch of the Euler product, and $\log\Phi(t)\sim\pi^{2}/(6t)$ ---
identical with the untruncated product governing $p(n)$. A standard transfer yields
$\log a(n)\sim2\sqrt{\pi^{2}n/6}=\pi\sqrt{2n/3}$. Rigorously, one replaces the crude inequality
$1-x^{i}\ge i/(8N)$ of Lemma~\ref{lem:tworegime} by the integral comparison
$\sum_{i}-\log(1-e^{-it})\le\pi^{2}/(6t)$ and tracks constants.

\subsection{Domination by the partition function}
\begin{conjecture}
$a(n)\le p(n)$ for all $n\ge0$.
\end{conjecture}
Verified for $n\le4000$. By Remark~\ref{rem:durfee} the inequality should hold layer by layer and
reduces to the monotonicity $p_{\le k-1}\le p_{\le k}$ once a formal Durfee bijection is available.
Domination is strict for $n\ge2$; e.g.\ $a(10)=9<42=p(10)$.

\subsection{Parity alternation of higher differences}
\begin{conjecture}
For each $b\ge2$, $c_{b}$ is a quasi-polynomial of degree $2b-1$ whose $(2b)$-th differences
alternate in sign according to the residue of $m$ modulo $\lcm(1,\dots,b)$.
\end{conjecture}
For $b=2$ the modulus is $2$ and the statement is Theorem~\ref{thm:d3}.

\subsection{Other core shapes}
Replacing the square-core condition by plateau width $w=\alpha k$ turns $x^{k^{2}}$ into
$x^{\alpha k^{2}}$ and rescales the saddle; $w=k^{\beta}$ interpolates between essentially
unrestricted stacks ($\beta=0$) and a strongly confined regime. For which exponents does the
``core is asymptotically free'' phenomenon, with constant $\pi\sqrt{2/3}$, survive?

\subsection{Refined statistics}
The saddle condition $kt=\log2$ with $t\sim\pi/\sqrt{6n}$ predicts that the core height of a
uniformly random square-core stack of area $n$ concentrates at
$k\approx\frac{\log2}{\pi}\sqrt{6n}\approx0.5406\sqrt n$, with fluctuations of order $n^{1/4}$.
Proving a local limit theorem for the core height is the natural probabilistic sequel.

\section{Algorithms}

\emph{Layer accumulation.} To tabulate $a(0..N)$, maintain the array $p_{\le k-1}(0..N)$; for
$k=0,1,2,\dots$ while $k^{2}\le N$, add the self-convolution of that array (truncated to length
$N-k^{2}+1$) into $a$ at offset $k^{2}$, then promote $p_{\le k-1}$ to $p_{\le k}$ by the in-place
coin-change update $p[m]\mathbin{+}=p[m-k]$ for $m=k,\dots,N$. Cost: $O(N^{2})$ integer
multiplications for the convolutions and $O(N^{3/2})$ additions for the updates.

\emph{Direct enumeration.} For validation, enumerate all $2^{n-1}$ compositions of $n$ and retain
those that are unimodal with maximal value $k$ occurring exactly $k$ times; agreement with the layer
formula holds for every $n\le16$ tested.

\emph{Closed-form third layer.} $c_{2}(m)$ is evaluated in $O(1)$ operations from
Theorem~\ref{thm:layer3}, both a speedup and a test.

\section{Conclusion}

A single geometric constraint --- the summit plateau must be a perfect square --- yields a counting
sequence with completely determined structure. The constraint becomes a ceiling on two slope
partitions, giving the layer decomposition and the generating function
$\sum_{k}x^{k^{2}}\prod_{i<k}(1-x^{i})^{-2}$, a one-factor truncation of the Durfee-square series.
From there: the sequence vanishes exactly at $n=2,3$; it is strictly increasing and convex
thereafter with divergent increments; convexity is optimal, since log-concavity fails at $n=8$ and
third-order convexity fails infinitely often, as the exact cubic quasi-polynomial of the third layer
shows. Globally $\log a(n)\asymp\sqrt n$: superpolynomial, subexponential, of vanishing entropy
density --- a rigid one-dimensional interface model whose asymptotic constant appears to coincide
with the Hardy--Ramanujan constant of the partition function.

