"""Visualisation: a gallery of square-core stack polyominoes, core highlighted."""

from __future__ import annotations

from typing import Iterator, List, Tuple

import matplotlib.pyplot as plt
from matplotlib.patches import Rectangle


def partitions_bounded(m: int, b: int) -> Iterator[List[int]]:
    """All weakly decreasing lists of positive parts <= b summing to m."""
    if m == 0:
        yield []
        return
    if b <= 0:
        return
    for part in range(min(b, m), 0, -1):
        for rest in partitions_bounded(m - part, part):
            yield [part] + rest


def square_core_stacks(n: int) -> Iterator[Tuple[int, List[int]]]:
    """Yield (core height k, column-height profile) for every square-core stack."""
    k = 0
    while k * k <= n:
        rest = n - k * k
        if k == 0:
            if rest == 0:
                yield 0, []
            k += 1
            continue
        for i in range(rest + 1):
            for left in partitions_bounded(i, k - 1):
                for right in partitions_bounded(rest - i, k - 1):
                    yield k, list(reversed(left)) + [k] * k + right
        k += 1


def main(n: int = 16, cols: int = 9) -> None:
    shapes = list(square_core_stacks(n))
    rows = (len(shapes) + cols - 1) // cols
    fig, axes = plt.subplots(rows, cols, figsize=(1.5 * cols, 1.7 * rows))
    axes = axes.ravel() if hasattr(axes, "ravel") else [axes]
    for ax in axes:
        ax.axis("off")
    for idx, (k, prof) in enumerate(shapes):
        ax = axes[idx]
        core_start = next(i for i, h in enumerate(prof) if h == k)
        for x, h in enumerate(prof):
            in_core = core_start <= x < core_start + k
            for y in range(h):
                ax.add_patch(Rectangle((x, y), 1, 1,
                                       facecolor="#ffcf5c" if in_core else
                                       ("#4fc3f7" if x < core_start else "#7e9bff"),
                                       edgecolor="white", lw=.6))
        ax.set_xlim(-0.3, max(len(prof), 1) + 0.3)
        ax.set_ylim(-0.3, max(prof + [1]) + 0.3)
        ax.set_aspect("equal")
        ax.set_title(f"$k={k}$", fontsize=9)
    fig.suptitle(f"All {len(shapes)} square-core stack polyominoes of area {n}\n"
                 "(gold = the $k\\times k$ core, blue = slopes with parts $<k$)",
                 fontsize=13)
    fig.tight_layout()
    fig.savefig(f"gallery_area_{n}.png", dpi=160)
    print(f"wrote gallery_area_{n}.png  ({len(shapes)} shapes)")


if __name__ == "__main__":
    main()
